(5540036, 800468, 41675, '<td valign="top">Soft, calming colors, good composition and I like the simple framing. Very well done and one of my top three picks. Good luck.</td>', 'Soft, calming colors, good composition and I like the simple framing. Very well done and one of my top three picks. Good luck.', '2009-06-22 18:04:16.000000', NULL, 1),
(5540038, 800920, 41675, '<td valign="top">Very simple yet very well captured, composed, lit, etc. One of my top three pics. Good luck!</td>', 'Very simple yet very well captured, composed, lit, etc. One of my top three pics. Good luck!', '2009-06-22 18:04:55.000000', NULL, 1),
(5540042, 800229, 41675, '<td valign="top">Zen or painful?! Ouch! Aside from the pain factor, nice bw study, great lighting and I like the negative spaces made by her arms &amp; legs. A certain top ten (at least I hope so) :-)</td>', 'Zen or painful?! Ouch! Aside from the pain factor, nice bw study, great lighting and I like the negative spaces made by her arms & legs. A certain top ten (at least I hope so) :-)', '2009-06-22 18:06:20.000000', NULL, 1),
(5540044, 800891, 41675, '<td valign="top">Very peaceful sunset. I like the way the rocks guide me into your image. An all around good image which I hope will be in the top ten. Best of luck.</td>', 'Very peaceful sunset. I like the way the rocks guide me into your image. An all around good image which I hope will be in the top ten. Best of luck.', '2009-06-22 18:07:13.000000', NULL, 1),
