(5542684, 801077, 43774, '<td valign="top">Love how the curve of the stone draws my eye into the photo towards the sun.</td>', 'Love how the curve of the stone draws my eye into the photo towards the sun.', '2009-06-24 17:15:00.000000', NULL, 1),
(5542685, 800824, 43774, '<td valign="top">Lovely macro, so sharp and clear.</td>', 'Lovely macro, so sharp and clear.', '2009-06-24 17:15:15.000000', NULL, 1),
