(5542920, 800905, 59029, '<td valign="top">Love that Joe Satriani song too! very nice shot, maybe a little oversharpened on tops of clouds.</td>', 'Love that Joe Satriani song too! very nice shot, maybe a little oversharpened on tops of clouds.', '2009-06-24 19:51:30.000000', NULL, 1),
(5542921, 800514, 3087, '<td valign="top">Lovely sharp detail, good lighting, nice clean background. Would like that drop at the leaf tip to be more prominent, to make it a more obvious focal point.</td>', 'Lovely sharp detail, good lighting, nice clean background. Would like that drop at the leaf tip to be more prominent, to make it a more obvious focal point.', '2009-06-24 19:52:06.000000', NULL, 1),
(5542922, 801102, 3087, '<td valign="top">Wow, that''s just gorgeous. Very Sher. Loving the textures, shapes and toning.</td>', 'Wow, that''s just gorgeous. Very Sher. Loving the textures, shapes and toning.', '2009-06-24 19:52:29.000000', NULL, 1),
(5542923, 801070, 3087, '<td valign="top">Lovely silhouettes. Usually I want to be closer to the wildlife but this shot puts them into their habitat and works wonderfully well.</td>', 'Lovely silhouettes. Usually I want to be closer to the wildlife but this shot puts them into their habitat and works wonderfully well.', '2009-06-24 19:53:05.000000', NULL, 1),
(5542924, 800961, 3087, '<td valign="top">Love it, just love it.</td>', 'Love it, just love it.', '2009-06-24 19:53:41.000000', NULL, 1),
(5542925, 800920, 3087, '<td valign="top">Gorgeous lighting, lovely composition/ crop, loving the crescent shape of the wings, echoed by the tail feathers. Wonderful!</td>', 'Gorgeous lighting, lovely composition/ crop, loving the crescent shape of the wings, echoed by the tail feathers. Wonderful!', '2009-06-24 19:54:41.000000', NULL, 1),
(5542927, 800549, 59029, '<td valign="top">Yes, very nice shot, great bokeh, purty flower...but...*ahem* I beg to differ, Spiffy...imho this is a divine Illuminatrix...<a href="//www.dpchallenge.com/image.php?IMAGE_ID=743569" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_challenge/hidden.png?1'', strrpos(''//images.dpchallenge.com/images_challenge/hidden.png?1'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_challenge/hidden.png?1"/></a> <br/> <br/>And if you aren''t Spiffy, my apologies! :-)</td>', 'Yes, very nice shot, great bokeh, purty flower...but...*ahem* I beg to differ, Spiffy...imho this is a divine Illuminatrix...  And if you aren''t Spiffy, my apologies! :-)', '2009-06-24 19:54:47.000000', NULL, 1),
